    for col in iter_column_marks(width, depth):
        j = col["index"]
        yield {"index": i, "id": f"physical:{j}",
               "kind": "PHYSICAL_SELECTOR", "target_role": "FIXED_ZERO",
               "selector_column": j, "selector_id": col["id"],
               "physical_coordinate": True}
